CREATE OR REPLACE FUNCTION check_block_allocation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE b public.room_blocks%ROWTYPE;bid uuid;BEGIN IF TG_TABLE_NAME='room_blocks' THEN bid=NEW.id;ELSE bid=NEW.block_id;END IF;IF bid IS NULL THEN RETURN NULL;END IF;SELECT * INTO b FROM public.room_blocks WHERE id=bid;IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.room_allocations a WHERE a.block_id=b.id AND a.organization_id=b.organization_id AND a.property_id=b.property_id AND a.room_id=b.room_id AND a.state=b.state AND a.starts_on=b.starts_on AND a.ends_on IS NOT DISTINCT FROM b.ends_on) THEN RAISE EXCEPTION 'INVALID_STATE' USING ERRCODE='P0409';END IF;RETURN NULL;END $$;
